const HEX: string = '0123456789ABCDEF';

function hexByte(value: number): string {
  return HEX[Math.floor(value / 16)] + HEX[value % 16];
}

function isUnreserved(ch: string): boolean {
  return /^[a-zA-Z0-9]$/.test(ch);
}

golden_completion:
function urlEncode(text: string, safe: string = ''): string {
  const bytes: Buffer = Buffer.from(text, 'utf-8');
  let out: string = '';
  for (const b of bytes) {
    const ch: string = String.fromCharCode(b);
    out += (b < 128 && (isUnreserved(ch) || safe.includes(ch))) ? ch : '%' + hexByte(b);
  }
  return out;
}

