      const filter = value.slice(pipeIndex + 1);
      value = context[key] || '';
      if (filter === 'upper') value = value.toUpperCase();
      else if (filter === 'lower') value = value.toLowerCase();
    } else {
      value = context[value] || ('%{' + expr + '}');
