// Custom string escape processor.
// Processes backslash escapes in a raw string:
//   \n => newline, \t => tab, \\\\ => backslash, \xHH => hex byte
//   \u{HHHH} => unicode codepoint (variable length, 1-6 hex digits)
//   Unknown escape \X => literal X (backslash consumed)
//
// CRITICAL: \x requires EXACTLY 2 hex digits; if fewer are available,
// treat as unknown escape (\x => 'x', digits kept as-is).
// \u{ requires } to close; if no }, treat as unknown escape.
//
// parseEscapes('a\\nb') => 'a\nb' (with actual newline)
// parseEscapes('\\x41') => 'A'
// parseEscapes('\\u{48}') => 'H'

golden_completion:
function parseEscapes(raw: string): string {
  let out = '', i = 0;
  while (i < raw.length) {
    if (raw[i] !== '\\' || i+1 >= raw.length) { out += raw[i++]; continue; }
    const c = raw[i+1];
    if (c==='n'){out+='\n';i+=2;} else if(c==='t'){out+='\t';i+=2;} else if(c==='\\'){out+='\\';i+=2;}
    else if (c==='x') { const h=raw.slice(i+2,i+4); if(/^[0-9a-fA-F]{2}$/.test(h)){out+=String.fromCharCode(parseInt(h,16));i+=4;} else{out+=c;i+=2;} }
    else if (c==='u'&&raw[i+2]==='{') { const e=raw.indexOf('}',i+3); if(e>=0){out+=String.fromCodePoint(parseInt(raw.slice(i+3,e),16));i=e+1;} else{out+=c;i+=2;} }
    else { out+=c; i+=2; }
  }
  return out;
}

