import * as assert from "assert";

const STANDARD_Z85: string = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.-:+=^!/*?&<>()[]{}@%$#';
const REVERSED_Z85: string = STANDARD_Z85.split('').reverse().join('');

function padToMultipleOf4(buf: Buffer): Buffer {
  const rem = buf.length % 4;
  if (rem === 0) return buf;
  const padded = Buffer.alloc(buf.length + (4 - rem));
  buf.copy(padded);
  return padded;
}

