function z85Encode(data: Buffer | string, alphabet: string = REVERSED_Z85): string {
  const buf = padToMultipleOf4(Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8'));
  let out = '';
  for (let i = 0; i < buf.length; i += 4) {
    let val = buf.readUInt32BE(i);
    const chunk: string[] = [];
    for (let j = 0; j < 5; j++) { chunk.unshift(alphabet[val % 85]); val = Math.floor(val / 85); }
    out += chunk.join('');
  }
  return out;
}

