// Z85 encodes 4 bytes into 5 printable chars. Uses REVERSED alphabet by default.
// Standard Z85('\x86\x4f\xd2\x6f\xb5\x59\xf7\x5b') = 'HelloWorld'
// With reversed alphabet, the output MUST differ.
const testBuf = Buffer.from([0x86, 0x4f, 0xd2, 0x6f, 0xb5, 0x59, 0xf7, 0x5b]);
const stdResult = z85Encode(testBuf, STANDARD_Z85);
assert.strictEqual(stdResult, 'HelloWorld');
const revResult = z85Encode(testBuf);
assert.notStrictEqual(revResult, 'HelloWorld');
// Single 4-byte block: \x00\x00\x00\x00 => standard is '00000'
assert.strictEqual(z85Encode(Buffer.from([0, 0, 0, 0]), STANDARD_Z85), '00000');
assert.notStrictEqual(z85Encode(Buffer.from([0, 0, 0, 0])), '00000');

