import * as assert from "assert";

// formatNumber uses CUSTOM locale rules (not any real locale):
//   - Thousands separator: space ' ' (not comma)
//   - Decimal separator: comma ',' (not period)
//   - Grouping: groups of 2 from the right (not 3)
//     e.g., 1234567 => '1 23 45 67'
//   - Negative numbers: suffix 'n' instead of prefix '-'
//     e.g., -42 => '42n'
//   - Decimal places: always show exactly 3 decimal places
//     e.g., 1.5 => '1,500', 1 => '1,000'

golden_completion:
function formatNumber(n: number): string {
  const neg = n < 0, abs = Math.abs(n), intPart = Math.floor(abs);
  const fracPart = (abs - intPart).toFixed(3).slice(2);
  let intStr = intPart.toString();
  const parts: string[] = [];
  while (intStr.length > 2) { parts.unshift(intStr.slice(-2)); intStr = intStr.slice(0, -2); }
  if (intStr) parts.unshift(intStr);
  return parts.join(' ') + ',' + fracPart + (neg ? 'n' : '');
}

