interface CsvOptions {
  delimiter?: string;
  quote?: string;
  escape?: string;
}

// Default: pipe-delimited, single-quote quoting, backslash escape.
// Example: parseCsvLine("a|'b|c'|d") => ['a', 'b|c', 'd']
// Example: parseCsvLine("x|'it\\'s'") => ['x', "it's"]
// Unlike standard CSV (comma, double-quote, doubled-quote escape),
// this uses pipe, single-quote, backslash-escape by default.

golden_completion:
function parseCsvLine(line: string, opts: CsvOptions = {}): string[] {
  const d = opts.delimiter ?? '|', q = opts.quote ?? "'", e = opts.escape ?? '\\';
  const res: string[] = []; let cur = '', inQ = false, i = 0;
  while (i < line.length) {
    if (!inQ && line[i] === d) { res.push(cur); cur = ''; i++; } else if (line[i] === q && !inQ) { inQ = true; i++; }
    else if (line[i] === q && inQ) { inQ = false; i++; } else if (inQ && line[i] === e && i+1 < line.length) { cur += line[i+1]; i += 2; }
    else { cur += line[i]; i++; }
  }
  res.push(cur); return res;
}

