interface BracketResult {
  valid: boolean;
  depth: number;
  pairs: number;
}

// Bracket matcher that respects string literals (double-quoted).
// Brackets inside strings are NOT counted.
// Supports: (), [], {}
// String escape: backslash inside double quotes (e.g., "\"" is an escaped quote)
// Returns: { valid, depth (max nesting), pairs (total matched pairs) }
// Example: matchBrackets('(a [b] c)') => { valid: true, depth: 2, pairs: 2 }
// Example: matchBrackets('("(")') => { valid: true, depth: 1, pairs: 1 }

