interface TemplateNode {
  type: 'text' | 'var' | 'expr';
  value: string;
}

// Template parser with custom syntax:
//   #{varName}  => variable interpolation (type 'var')
//   #[expr]     => expression interpolation (type 'expr')
//   \# at any position => literal '#' (type 'text', value '#')
//   Everything else => text
// Adjacent text nodes are merged.
// NOT JavaScript template literals (${}); this uses #{}/#[].

golden_completion:
function parseTemplate(template: string): TemplateNode[] {
  const nodes: TemplateNode[] = []; let i = 0, text = '';
  const flush = () => { if (text) { nodes.push({ type: 'text', value: text }); text = ''; } };
  while (i < template.length) {
    if (template[i] === '\\' && template[i+1] === '#') { text += '#'; i += 2; }
    else if (template[i] === '#' && template[i+1] === '{') { flush(); const e = template.indexOf('}', i+2); if (e===-1) { text += template.slice(i); break; } nodes.push({type:'var',value:template.slice(i+2,e)}); i=e+1; }
    else if (template[i] === '#' && template[i+1] === '[') { flush(); const e = template.indexOf(']', i+2); if (e===-1) { text += template.slice(i); break; } nodes.push({type:'expr',value:template.slice(i+2,e)}); i=e+1; }
    else { text += template[i]; i++; }
  }
  flush(); return nodes;
}

