interface PipeResult<T> {
  ok: boolean;
  value?: T;
  error?: string;
  stage?: string;
}

type PipeStage<I, O> = {
  name: string;
  fn: (input: I) => O;
};

// Pipeline that runs stages sequentially. If any stage throws, capture
// the error message and the stage name. Return { ok, value, error, stage }.
// Each stage's output is the next stage's input.
// An empty pipeline returns { ok: true, value: input }.
// Stages are typed but at runtime we use 'any' for chaining.

golden_completion:
function runPipeline<T>(input: T, stages: PipeStage<any, any>[]): PipeResult<any> {
  let current: any = input;
  for (const stage of stages) {
    try {
      current = stage.fn(current);
    } catch (e: any) {
      return { ok: false, error: e.message ?? String(e), stage: stage.name };
    }
  }
  return { ok: true, value: current };
}

