function diffLines(oldLines: string[], newLines: string[]): DiffOp[] {
  const oldLineCounts: { [line: string]: number } = {};
  const newLineCounts: { [line: string]: number } = {};
  const oldLineIndices: { [line: string]: number } = {};
  const newLineIndices: { [line: string]: number } = {};

  oldLines.forEach((line, index) => {
    oldLineCounts[line] = (oldLineCounts[line] || 0) + 1;
    oldLineIndices[line] = index;
  });

  newLines.forEach((line, index) => {
    newLineCounts[line] = (newLineCounts[line] || 0) + 1;
    newLineIndices[line] = index;
  });

  const diff: DiffOp[] = [];

  newLines.forEach((line, index) => {
    if (line in oldLineCounts && oldLineCounts[line] === 1 && newLineCounts[line] === 1 && oldLineIndices[line] !== index) {
      diff.push({ type: 'move', line, from: oldLineIndices[line], to: index });
    } else if (!(line in oldLineCounts) || oldLineCounts[line] === 0) {
      diff.push({ type: 'add', line });
    } else {
      diff.push({ type: 'keep', line });
      oldLineCounts[line]--;
    }
  });

  Object.keys(oldLineCounts).forEach(line => {
    for (let i = 0; i < oldLineCounts[line]; i++) {
      diff.splice(newLineIndices[line], 0, { type: 'remove', line });
    }
  });

  return diff;
}

