const counter: Reducer<number> = (state, action) => {
  switch (action.type) {
    case 'INC': return state + (action.payload || 1);
    case 'DEC': return state - (action.payload || 1);
    default: return state;
  }
};

// No middleware
const s1 = createStore(counter, 0);
s1.dispatch({ type: 'INC' });
assert.strictEqual(s1.getState(), 1);
s1.dispatch({ type: 'INC', payload: 5 });
assert.strictEqual(s1.getState(), 6);

// Middleware that doubles INC payloads
const doubler: Middleware<number> = (state, action, next) => {
  if (action.type === 'INC') {
    return next({ type: 'INC', payload: (action.payload || 1) * 2 });
  }
  return next(action);
};

const s2 = createStore(counter, 0, [doubler]);
s2.dispatch({ type: 'INC' });
assert.strictEqual(s2.getState(), 2);
s2.dispatch({ type: 'DEC' });
assert.strictEqual(s2.getState(), 1);

