class PipelineImpl<T> implements Pipeline<T> {
  private iter: Iterable<T>;

  constructor(iter: Iterable<T>) {
    this.iter = iter;
  }

  map<U>(fn: (x: T) => U): Pipeline<U> {
    return new PipelineImpl(function* (iter: Iterable<T>) {
      for (const x of iter) {
        yield fn(x);
      }
    }(this.iter));
  }

  filter(fn: (x: T) => boolean): Pipeline<T> {
    return new PipelineImpl(function* (iter: Iterable<T>) {
      for (const x of iter) {
        if (fn(x)) {
          yield x;
        }
      }
    }(this.iter));
  }

  take(n: number): Pipeline<T> {
    return new PipelineImpl(function* (iter: Iterable<T>, n: number) {
      let count = 0;
      for (const x of iter) {
        if (count >= n) {
          break;
        }
        yield x;
        count++;
      }
    }(this.iter, n));
  }

  toArray(): T[] {
    return Array.from(this.iter);
  }
}

function pipeline<T>(iter: Iterable<T>): Pipeline<T> {
  return new PipelineImpl(iter);
}

