function createMachine<C>(transitions: Transition<C>[], initialState: string, initialContext: C): { send: (event: string) => MachineResult<C> } {
  let state = initialState;
  let context = initialContext;
  let history = [initialState];

  function send(event: string): MachineResult<C> {
    const matchingTransitions = transitions.filter(t => t.from === state && t.event === event);
    const validTransition = matchingTransitions.find(t => !t.guard || t.guard(context));

    if (validTransition) {
      if (validTransition.action) {
        validTransition.action(context);
      }
      state = validTransition.to;
      history.push(state);
    }

    return { state, context, history };
  }

  return { send };
}

